, 'required' => true, 'autocomplete' => true], ], ], ], ]; } public static function hash(array $commands): string { return hash('sha256', json_encode($commands, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)); } public static function server(): array { return [ 'type' => self::STRING, 'name' => 'server', 'description' => 'Start typing a server name.', 'required' => true, 'autocomplete' => true, ]; } private static function command(string $name, string $description, array $options = []): array { return array_filter([ 'name' => $name, 'description' => $description, 'type' => 1, 'options' => $options === [] ? null : $options, ], fn ($value) => $value !== null); } } 